/**
 * Home.jsx
 * Main landing page with real-time clock display and search tools functionality
 * Redesigned with premium glassmorphism and modern visual language
 */

import React, { useState, useEffect } from 'react';
import { Home as HomeIcon, Clock, Search, ArrowRight } from 'lucide-react';
import { TOOL_CATALOG } from '../utils/toolCategories';
import { trackEvent } from '../utils/analytics';

const Home = ({ searchNavigation, onNavigate }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [searchQuery, setSearchQuery] = useState('');
  const [filteredTools, setFilteredTools] = useState([]);

  useEffect(() => {
    // Update time immediately on mount
    setCurrentTime(new Date());

    // Set up interval to update every second
    const timeInterval = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    // Cleanup interval on component unmount
    return () => {
      clearInterval(timeInterval);
    };
  }, []);

  // Search functionality for homepage
  useEffect(() => {
    if (searchQuery.trim()) {
      const filtered = TOOL_CATALOG.filter(tool =>
        tool.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        tool.title?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        tool.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        tool.category.toLowerCase().includes(searchQuery.toLowerCase())
      );
      setFilteredTools(filtered.slice(0, 6)); // Limit to 6 results
    } else {
      setFilteredTools([]);
    }
  }, [searchQuery]);

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim() && filteredTools.length > 0) {
      const tool = filteredTools[0];
      onNavigate(tool.page, tool.toolId);
      trackEvent('search_tool_select', {
        tool_name: tool.name || tool.title,
        search_query: searchQuery
      });
    }
  };

  const handleToolClick = (tool) => {
    // Fix navigation by using the correct properties
    const categoryId = tool.categoryId || tool.category?.toLowerCase().replace(/\s+/g, '-');
    const toolId = tool.id || tool.toolId;

    if (onNavigate && categoryId && toolId) {
      onNavigate(categoryId, toolId);
      trackEvent('home_tool_click', {
        tool_name: tool.name || tool.title,
        category: tool.category
      });
    }
  };

  // Time formatting functions
  const formatTime = (date) => {
    return date.toLocaleTimeString('en-US', {
      hour12: true,
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  const formatDate = (date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  // Get category color class for tool cards
  const getCategoryColorClass = (category) => {
    const colorMap = {
      'Stock Market': 'tool-card-yellow',
      'Games': 'tool-card-purple',
      'Calculators': 'tool-card-blue',
      'Tools': 'tool-card-green',
      'Productivity': 'tool-card-orange'
    };
    return colorMap[category] || 'tool-card-blue';
  };

  // Get icon color based on category for search results
  const getCategoryIconColor = (category) => {
    const colorMap = {
      'Stock Market': 'rgb(255, 215, 0)', // Gold
      'Games': 'rgb(128, 0, 128)', // Purple
      'Calculators': 'rgb(0, 128, 255)', // Blue
      'Tools': 'rgb(0, 255, 145)', // Green
      'Productivity': 'rgb(255, 165, 0)' // Orange
    };
    return colorMap[category] || 'rgb(0, 128, 255)'; // Default to blue
  };

  // Group tools by category for better organization
  const groupedTools = TOOL_CATALOG.reduce((acc, tool) => {
    const category = tool.category;
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(tool);
    return acc;
  }, {});

  return (
    <div className="space-y-12 pb-12">
      {/* Welcome Header */}
      <div className="text-center space-y-6 pt-8">
        <div className="flex items-center justify-center space-x-4 mb-6">
          <div className="p-3 glass-card-strong micro-bounce float-animation">
            <HomeIcon className="w-8 h-8" style={{color: 'rgb(0, 255, 145)'}} />
          </div>
          <h1 className="text-5xl font-light text-white tracking-tight">
            AllInOne Dashboard
          </h1>
        </div>
        <p className="text-xl text-gray-300 max-w-3xl mx-auto font-light text-premium">
          Your comprehensive productivity hub with real-time tools and seamless navigation
        </p>
      </div>

      {/* Premium Time Display */}
      <div className="max-w-4xl mx-auto">
        <div className="time-display p-12 text-center pulse-glow">
          <div className="time-display-content space-y-6">
            <div className="flex items-center justify-center space-x-3 mb-6">
              <Clock className="w-8 h-8" style={{color: 'rgb(0, 255, 145)'}} />
              <h2 className="text-3xl font-light text-premium">Current Time</h2>
            </div>
            <div className="text-7xl font-extralight mb-4 tracking-tight" style={{color: 'rgb(0, 255, 145)'}}>
              {formatTime(currentTime)}
            </div>
            <div className="text-2xl text-gray-600 dark:text-gray-300 font-light text-premium">
              {formatDate(currentTime)}
            </div>
          </div>
        </div>
      </div>

      {/* Modern Search Bar */}
      <div className="max-w-2xl mx-auto">
        <div className="glass-card-strong p-8">
          <div className="flex items-center space-x-3 mb-6">
            <Search className="w-6 h-6" style={{color: 'rgb(0, 255, 145)'}} />
            <h3 className="text-2xl font-light text-premium">Quick Tool Search</h3>
          </div>

          <form onSubmit={handleSearch} className="relative">
            <div className="search-floating">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search for calculators, games, productivity tools..."
                className="w-full p-6 bg-transparent text-gray-900 dark:text-white
                         placeholder-gray-500 dark:placeholder-gray-400 text-lg
                         focus:outline-none transition-all duration-300 text-premium"
              />
            </div>

            {/* Search Results Dropdown */}
            {filteredTools.length > 0 && (
              <div className="search-dropdown">
                {filteredTools.map((tool, index) => (
                  <button
                    key={index}
                    onClick={() => handleToolClick(tool)}
                    className="w-full text-left p-4 hover:bg-white/10 transition-all duration-200
                             flex items-center justify-between group"
                  >
                    <div className="flex items-center space-x-3">
                      {tool.icon && <tool.icon className="w-5 h-5" style={{color: getCategoryIconColor(tool.category)}} />}
                      <div>
                        <div className="font-medium text-gray-900 dark:text-white text-premium">
                          {tool.name || tool.title}
                        </div>
                        <div className="text-sm text-gray-600 dark:text-gray-400 text-premium">
                          {tool.description}
                        </div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-gray-400 group-hover:text-blue-400
                                         transition-colors duration-200 micro-bounce" />
                  </button>
                ))}
              </div>
            )}
          </form>
        </div>
      </div>

      {/* All Applications by Category */}
      <div className="max-w-7xl mx-auto">
        <div className="glass-card p-8">
          <h3 className="text-3xl font-light text-premium mb-8">All Applications</h3>

          <div className="space-y-12">
            {Object.entries(groupedTools).map(([category, tools]) => {
              const colorClass = getCategoryColorClass(category);

              return (
                <div key={category}>
                  <h4 className="text-2xl font-light text-premium mb-6 flex items-center space-x-3">
                    <span>{category}</span>
                    <span className="text-sm px-3 py-1 rounded-full bg-gray-200 dark:bg-gray-700
                                   text-gray-700 dark:text-gray-300">
                      {tools.length}
                    </span>
                  </h4>

                  <div className="premium-grid">
                    {tools.map((tool, index) => {
                      const IconComponent = tool.icon;

                      return (
                        <button
                          key={`${tool.id || tool.toolId || index}`}
                          onClick={() => handleToolClick(tool)}
                          className={`tool-card ${colorClass} p-6 text-left group`}
                        >
                          <div className="relative z-10">
                            <div className="flex items-center justify-between mb-4">
                              <div className="p-3 glass-card micro-bounce">
                                {IconComponent && <IconComponent className="w-6 h-6" style={{color: getCategoryIconColor(tool.category)}} />}
                              </div>
                              <ArrowRight className="w-5 h-5 text-gray-400 group-hover:text-white
                                                   transition-all duration-300 group-hover:translate-x-1" />
                            </div>

                            <h5 className="text-xl font-medium text-white mb-2 text-premium">
                              {tool.name || tool.title}
                            </h5>

                            <p className="text-gray-300 text-premium leading-relaxed">
                              {tool.description}
                            </p>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
