/**
 * Games.jsx
 * Games and entertainment page with modular game selection
 */

import React from 'react';
import { Gamepad2, Zap, Target } from 'lucide-react';
import SnakeGame from '../components/SnakeGame';
import DartGame from '../components/DartGame';
import ModulePage from '../components/ModulePage';

const Games = ({ searchNavigation }) => {
  // Available game modules
  const gameModules = [
    {
      id: 'snake',
      title: 'Snake Game',
      description: 'Classic Snake game with smooth animations and sprite graphics. Eat the fruits to grow your snake and increase your score!',
      icon: Zap,
      status: 'available',
      component: SnakeGame
    },
    {
      id: 'dart',
      title: 'Dart Game',
      description: 'Test your skills with our Dart Game. Aim for the bullseye and score points to win!',
      icon: Target,
      status: 'available',
      component: DartGame
    }
  ];

  return (
    <ModulePage
      title="Games & Entertainment"
      icon={Gamepad2}
      modules={gameModules}
      searchNavigation={searchNavigation}
      colorTheme="purple"
      eventPrefix="games_game"
      buttonText="Play Game"
    />
  );
};

export default Games;
