/**
 * OptionPricingTool.jsx
 * Professional Option Pricing Tool with Black-Scholes pricing and Greeks
 */

import React, { useState } from 'react';
import { Calculator, Info, ChevronDown, ChevronUp, Settings, TrendingUp, Target, HelpCircle, BarChart3, Eye, EyeOff, FileSpreadsheet, TrendingDown } from 'lucide-react';
import { useOptionPricing } from '../hooks/useOptionPricing';
import { useOptionLadder } from '../hooks/useOptionLadder';
import OptionChart from './OptionChart';
import PayoffChart from './PayoffChart';
import * as XLSX from 'xlsx';

const OptionPricingTool = () => {
  const {
    parameters,
    updateParameter,
    results,
    validation,
    calculateOptionPrice,
    calculateGreeks
  } = useOptionPricing();

  const {
    ladderConfig,
    updateLadderConfig,
    isExpanded,
    setIsExpanded,
    availableGreeks,
    toggleGreek,
    generateLadder,
    ladderValidation,
    formatExpiration,
    formatPrice,
    formatPercentage
  } = useOptionLadder(calculateOptionPrice, calculateGreeks);

  // Chart expansion state
  const [isChartExpanded, setIsChartExpanded] = useState(false);

  // Payoff chart expansion state
  const [isPayoffChartExpanded, setIsPayoffChartExpanded] = useState(false);

  // Strangle spread configuration
  const [strangleSpread, setStrangleSpread] = useState(5);

  // Format number for display
  const formatNumber = (num, decimals = 2) => {
    if (isNaN(num) || !isFinite(num)) return 'N/A';
    return num.toFixed(decimals);
  };

  // Calculate straddle and strangle prices
  const calculateStraddleStrangle = () => {
    if (!validation.isValid) return { straddle: 0, strangle: 0 };

    // Straddle: ATM call + ATM put
    const straddlePrice = results.callPrice + results.putPrice;

    // Strangle: OTM call + OTM put
    const strangleCallStrike = parameters.K + strangleSpread;
    const stranglePutStrike = parameters.K - strangleSpread;

    const strangleCall = calculateOptionPrice(
      parameters.S,
      strangleCallStrike,
      parameters.T,
      parameters.r,
      parameters.sigma,
      parameters.q,
      'call'
    );

    const stranglePut = calculateOptionPrice(
      parameters.S,
      stranglePutStrike,
      parameters.T,
      parameters.r,
      parameters.sigma,
      parameters.q,
      'put'
    );

    const stranglePrice = strangleCall + stranglePut;

    return {
      straddle: straddlePrice,
      strangle: stranglePrice,
      strangleCallStrike,
      stranglePutStrike
    };
  };

  // Export option data to Excel
  const exportToExcel = () => {
    if (!validation.isValid) return;

    const wb = XLSX.utils.book_new();

    // Basic pricing data
    const basicData = [
      { Parameter: 'Stock Price', Value: parameters.S },
      { Parameter: 'Strike Price', Value: parameters.K },
      { Parameter: 'Time to Expiration', Value: parameters.T },
      { Parameter: 'Volatility', Value: parameters.sigma },
      { Parameter: 'Risk-free Rate', Value: parameters.r },
      { Parameter: 'Dividend Yield', Value: parameters.q },
      { Parameter: '', Value: '' },
      { Parameter: 'Call Price', Value: results.callPrice },
      { Parameter: 'Put Price', Value: results.putPrice },
      { Parameter: '', Value: '' },
      { Parameter: 'Call Delta', Value: results.callDelta },
      { Parameter: 'Put Delta', Value: results.putDelta },
      { Parameter: 'Gamma', Value: results.gamma },
      { Parameter: 'Call Theta', Value: results.callTheta },
      { Parameter: 'Put Theta', Value: results.putTheta },
      { Parameter: 'Vega', Value: results.vega },
      { Parameter: 'Call Rho', Value: results.callRho },
      { Parameter: 'Put Rho', Value: results.putRho }
    ];

    const ws1 = XLSX.utils.json_to_sheet(basicData);
    XLSX.utils.book_append_sheet(wb, ws1, 'Basic Pricing');

    // Option chain data if available
    if (isExpanded && ladderData.length > 0) {
      const chainData = ladderData.map(row => ({
        [ladderConfig.mode === 'strike' ? 'Strike' : 'Expiration']:
          ladderConfig.mode === 'strike' ? row.strike : row.expiration,
        'Call Price': row.call.price,
        'Call Delta': row.call.delta,
        'Call Gamma': row.call.gamma,
        'Call Theta': row.call.theta,
        'Call Vega': row.call.vega,
        'Call Rho': row.call.rho,
        'Put Price': row.put.price,
        'Put Delta': row.put.delta,
        'Put Gamma': row.put.gamma,
        'Put Theta': row.put.theta,
        'Put Vega': row.put.vega,
        'Put Rho': row.put.rho
      }));

      const ws2 = XLSX.utils.json_to_sheet(chainData);
      XLSX.utils.book_append_sheet(wb, ws2, 'Option Chain');
    }

    XLSX.writeFile(wb, `Option_Analysis_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  // Compact input field component
  const CompactInput = ({ label, value, onChange, tooltip, suffix = '', type = 'number', step = 'any' }) => (
    <div className="space-y-1">
      <div className="flex items-center space-x-1">
        <label className="text-xs font-medium text-gray-700 dark:text-gray-300">
          {label}
        </label>
        {tooltip && (
          <div className="group relative">
            <HelpCircle className="w-3 h-3 text-gray-400 cursor-help" />
            <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-1 px-2 py-1 text-xs text-white bg-gray-900 rounded opacity-0 group-hover:opacity-100 transition-opacity duration-200 whitespace-nowrap z-10">
              {tooltip}
            </div>
          </div>
        )}
      </div>
      <div className="relative">
        <input
          type={type}
          step={step}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-full px-2 py-1 text-sm border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-1 focus:ring-blue-500 focus:border-transparent font-mono"
        />
        {suffix && (
          <span className="absolute right-2 top-1 text-xs text-gray-500">{suffix}</span>
        )}
      </div>
    </div>
  );

  // Generate ladder data
  const ladderData = isExpanded ? generateLadder(parameters) : [];

  return (
    <div className="space-y-4">
      {/* Compact Header */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Calculator className="w-6 h-6 text-blue-600" />
            <div>
              <h1 className="text-xl font-bold text-gray-900 dark:text-white">Option Pricing Tool</h1>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Black-Scholes pricing with Greeks analysis and option chain generator
              </p>
            </div>
          </div>
          {validation.isValid && (
            <button
              onClick={exportToExcel}
              className="flex items-center space-x-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
            >
              <FileSpreadsheet className="w-4 h-4" />
              <span>Export</span>
            </button>
          )}
        </div>
      </div>

      {/* Main Content - Horizontal Spreadsheet Layout */}
      <div className="grid grid-cols-1 xl:grid-cols-4 gap-4">

        {/* 🔧 Input Parameters - Compact Vertical */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4 border-l-4 border-blue-500">
          <h2 className="text-sm font-semibold text-blue-700 dark:text-blue-300 mb-3 flex items-center">
            <Settings className="w-4 h-4 mr-2" />
            Parameters
          </h2>

          <div className="space-y-3">
            <CompactInput
              label="Stock Price"
              value={parameters.S}
              onChange={(value) => updateParameter('S', value)}
              tooltip="Current stock price"
              suffix="$"
            />
            <CompactInput
              label="Strike Price"
              value={parameters.K}
              onChange={(value) => updateParameter('K', value)}
              tooltip="Exercise price"
              suffix="$"
            />
            <CompactInput
              label="Time to Exp."
              value={parameters.T}
              onChange={(value) => updateParameter('T', value)}
              tooltip="Years to expiration"
              suffix="yr"
              step="0.01"
            />
            <CompactInput
              label="Volatility"
              value={parameters.sigma}
              onChange={(value) => updateParameter('sigma', value)}
              tooltip="Annual volatility (decimal)"
              step="0.01"
            />
            <CompactInput
              label="Risk-free Rate"
              value={parameters.r}
              onChange={(value) => updateParameter('r', value)}
              tooltip="Risk-free rate (decimal)"
              step="0.001"
            />
            <CompactInput
              label="Dividend Yield"
              value={parameters.q}
              onChange={(value) => updateParameter('q', value)}
              tooltip="Dividend yield (decimal)"
              step="0.001"
            />

            {/* Strangle Spread Configuration */}
            <div className="mt-4 pt-3 border-t border-gray-200 dark:border-gray-700">
              <CompactInput
                label="Strangle Spread"
                value={strangleSpread}
                onChange={(value) => setStrangleSpread(parseFloat(value) || 5)}
                tooltip="Strike price difference for strangle (±)"
                suffix="$"
                step="1"
              />
            </div>
          </div>

          {/* Validation Errors */}
          {!validation.isValid && (
            <div className="mt-3 p-2 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded text-xs">
              <div className="font-medium text-red-800 dark:text-red-200 mb-1">Errors:</div>
              <ul className="text-red-700 dark:text-red-300 space-y-0.5">
                {validation.errors.map((error, index) => (
                  <li key={index}>• {error}</li>
                ))}
              </ul>
            </div>
          )}
        </div>

        {/* 💵 Pricing Models - Spreadsheet Style */}
        <div className="xl:col-span-2 bg-white dark:bg-gray-800 rounded-lg shadow-sm overflow-hidden border-l-4 border-green-500">
          <div className="bg-gradient-to-r from-green-50 to-emerald-50 dark:from-green-900/20 dark:to-emerald-900/20 px-4 py-3 border-b border-gray-200 dark:border-gray-700">
            <h2 className="text-sm font-semibold text-green-700 dark:text-green-300 flex items-center">
              <Calculator className="w-4 h-4 mr-2" />
              Option Pricing Models
            </h2>
          </div>

          {validation.isValid ? (
            <div className="p-4">
              {/* Pricing Table Header */}
              <div className="grid grid-cols-3 gap-3 mb-3 text-xs font-semibold text-gray-600 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 pb-2">
                <div className="text-left">Option Type</div>
                <div className="text-center">Binomial Model</div>
                <div className="text-center">Black-Scholes</div>
              </div>

              {/* Call Option Row */}
              <div className="grid grid-cols-3 gap-3 mb-3 py-3 bg-green-50 dark:bg-green-900/10 rounded-lg border border-green-200 dark:border-green-800">
                <div className="flex items-center">
                  <div className="w-3 h-3 bg-green-500 rounded-full mr-2"></div>
                  <div>
                    <div className="text-sm font-medium text-green-800 dark:text-green-200">Call Option</div>
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-green-900 dark:text-green-100">
                    {formatPrice(results.binomialCallPrice)}
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-green-900 dark:text-green-100">
                    {formatPrice(results.callPrice)}
                  </div>
                </div>
              </div>

              {/* Put Option Row */}
              <div className="grid grid-cols-3 gap-3 py-3 bg-red-50 dark:bg-red-900/10 rounded-lg border border-red-200 dark:border-red-800">
                <div className="flex items-center">
                  <div className="w-3 h-3 bg-red-500 rounded-full mr-2"></div>
                  <div>
                    <div className="text-sm font-medium text-red-800 dark:text-red-200">Put Option</div>
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-red-900 dark:text-red-100">
                    {formatPrice(results.binomialPutPrice)}
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-red-900 dark:text-red-100">
                    {formatPrice(results.putPrice)}
                  </div>
                </div>
              </div>

              {/* Straddle Row */}
              <div className="grid grid-cols-3 gap-3 mt-3 py-3 bg-yellow-50 dark:bg-yellow-900/10 rounded-lg border border-yellow-200 dark:border-yellow-800">
                <div className="flex items-center">
                  <div className="w-3 h-3 bg-yellow-500 rounded-full mr-2"></div>
                  <div>
                    <div className="text-sm font-medium text-yellow-800 dark:text-yellow-200">Straddle</div>
                    <div className="text-xs text-yellow-600 dark:text-yellow-400">ATM Call + ATM Put</div>
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-yellow-900 dark:text-yellow-100">
                    {formatPrice(calculateStraddleStrangle().straddle)}
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-yellow-900 dark:text-yellow-100">
                    {formatPrice(calculateStraddleStrangle().straddle)}
                  </div>
                </div>
              </div>

              {/* Strangle Row */}
              <div className="grid grid-cols-3 gap-3 py-3 bg-yellow-50 dark:bg-yellow-900/10 rounded-lg border border-yellow-200 dark:border-yellow-800">
                <div className="flex items-center">
                  <div className="w-3 h-3 bg-yellow-500 rounded-full mr-2"></div>
                  <div>
                    <div className="text-sm font-medium text-yellow-800 dark:text-yellow-200">Strangle</div>
                    <div className="text-xs text-yellow-600 dark:text-yellow-400">
                      {parameters.K - strangleSpread}C + {parameters.K + strangleSpread}P
                    </div>
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-yellow-900 dark:text-yellow-100">
                    {formatPrice(calculateStraddleStrangle().strangle)}
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold font-mono text-yellow-900 dark:text-yellow-100">
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center text-gray-500 dark:text-gray-400 text-sm py-8">
              Fix input errors to see pricing models
            </div>
          )}
        </div>

        {/* 📊 Greeks - Compact Table */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm overflow-hidden border-l-4 border-purple-500">
          <div className="bg-gradient-to-r from-purple-50 to-violet-50 dark:from-purple-900/20 dark:to-violet-900/20 px-4 py-3 border-b border-gray-200 dark:border-gray-700">
            <h2 className="text-sm font-semibold text-purple-700 dark:text-purple-300 flex items-center">
              <Target className="w-4 h-4 mr-2" />
              Greeks
            </h2>
          </div>

          {validation.isValid ? (
            <div className="p-4">
              <div className="space-y-3">
                {/* Delta */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700">
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">Delta</div>
                    <div className="text-xs text-gray-500">Price sensitivity</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-mono text-green-600">C: {formatNumber(results.callDelta, 3)}</div>
                    <div className="text-sm font-mono text-red-600">P: {formatNumber(results.putDelta, 3)}</div>
                  </div>
                </div>

                {/* Gamma */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700">
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">Gamma</div>
                    <div className="text-xs text-gray-500">Delta sensitivity</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-mono text-blue-600">{formatNumber(results.gamma, 4)}</div>
                    <div className="text-xs text-gray-400">Both options</div>
                  </div>
                </div>

                {/* Theta */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700">
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">Theta</div>
                    <div className="text-xs text-gray-500">Time decay</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-mono text-green-600">C: {formatNumber(results.callTheta, 3)}</div>
                    <div className="text-sm font-mono text-red-600">P: {formatNumber(results.putTheta, 3)}</div>
                  </div>
                </div>

                {/* Vega */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100 dark:border-gray-700">
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">Vega</div>
                    <div className="text-xs text-gray-500">Vol sensitivity</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-mono text-blue-600">{formatNumber(results.vega, 3)}</div>
                    <div className="text-xs text-gray-400">Both options</div>
                  </div>
                </div>

                {/* Rho */}
                <div className="flex justify-between items-center py-2">
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">Rho</div>
                    <div className="text-xs text-gray-500">Rate sensitivity</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-mono text-green-600">C: {formatNumber(results.callRho, 3)}</div>
                    <div className="text-sm font-mono text-red-600">P: {formatNumber(results.putRho, 3)}</div>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center text-gray-500 dark:text-gray-400 text-sm py-8">
              Fix input errors to see Greeks
            </div>
          )}
        </div>
      </div>

      {/* 📉 Option Ladder (Chain) Section */}
      {validation.isValid && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <TrendingUp className="w-5 h-5 text-purple-600" />
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Option Chain</h2>
            </div>
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className="flex items-center space-x-1 px-3 py-1 bg-purple-600 text-white rounded text-sm hover:bg-purple-700 transition-colors"
            >
              <span>{isExpanded ? 'Hide' : 'Show'}</span>
              {isExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>
          </div>

          {isExpanded && (
            <div className="space-y-4">
              {/* Compact Configuration */}
              <div className="border border-gray-200 dark:border-gray-700 rounded p-3">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-3 items-end">
                  {/* Mode Selection */}
                  <div>
                    <label className="text-xs font-medium text-gray-700 dark:text-gray-300 mb-1 block">Type</label>
                    <div className="flex space-x-2 text-xs">
                      <label className="flex items-center">
                        <input
                          type="radio"
                          checked={ladderConfig.mode === 'strike'}
                          onChange={() => updateLadderConfig('mode', 'strike')}
                          className="mr-1"
                        />
                        <span>Strikes</span>
                      </label>
                      <label className="flex items-center">
                        <input
                          type="radio"
                          checked={ladderConfig.mode === 'expiration'}
                          onChange={() => updateLadderConfig('mode', 'expiration')}
                          className="mr-1"
                        />
                        <span>Expirations</span>
                      </label>
                    </div>
                  </div>

                  {/* Range Configuration */}
                  {ladderConfig.mode === 'strike' ? (
                    <>
                      <CompactInput
                        label="Min Strike"
                        value={ladderConfig.strikeMin}
                        onChange={(value) => updateLadderConfig('strikeMin', parseFloat(value) || 0)}
                        suffix="$"
                      />
                      <CompactInput
                        label="Max Strike"
                        value={ladderConfig.strikeMax}
                        onChange={(value) => updateLadderConfig('strikeMax', parseFloat(value) || 0)}
                        suffix="$"
                      />
                      <CompactInput
                        label="Step"
                        value={ladderConfig.strikeStep}
                        onChange={(value) => updateLadderConfig('strikeStep', parseFloat(value) || 1)}
                        suffix="$"
                      />
                    </>
                  ) : (
                    <>
                      <CompactInput
                        label="Min Time"
                        value={ladderConfig.expirationMin}
                        onChange={(value) => updateLadderConfig('expirationMin', parseFloat(value) || 0)}
                        suffix="yr"
                        step="0.1"
                      />
                      <CompactInput
                        label="Max Time"
                        value={ladderConfig.expirationMax}
                        onChange={(value) => updateLadderConfig('expirationMax', parseFloat(value) || 0)}
                        suffix="yr"
                        step="0.1"
                      />
                      <CompactInput
                        label="Step"
                        value={ladderConfig.expirationStep}
                        onChange={(value) => updateLadderConfig('expirationStep', parseFloat(value) || 0.1)}
                        suffix="yr"
                        step="0.1"
                      />
                    </>
                  )}
                </div>
              </div>

              {/* Greek Selection Toggles */}
              <div className="border border-gray-200 dark:border-gray-700 rounded p-3">
                <label className="text-xs font-medium text-gray-700 dark:text-gray-300 mb-2 block">
                  Greeks to Display
                </label>
                <div className="flex flex-wrap gap-2">
                  {availableGreeks.map(greek => (
                    <button
                      key={greek.key}
                      onClick={() => toggleGreek(greek.key)}
                      className={`flex items-center space-x-1 px-2 py-1 rounded text-xs transition-colors ${
                        ladderConfig.visibleGreeks.includes(greek.key)
                          ? 'bg-blue-100 text-blue-800 border border-blue-300 dark:bg-blue-900/20 dark:text-blue-200 dark:border-blue-700'
                          : 'bg-gray-100 text-gray-600 border border-gray-300 dark:bg-gray-700 dark:text-gray-400 dark:border-gray-600'
                      }`}
                    >
                      {ladderConfig.visibleGreeks.includes(greek.key) ? (
                        <Eye className="w-3 h-3" />
                      ) : (
                        <EyeOff className="w-3 h-3" />
                      )}
                      <span>{greek.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Option Chain Table */}
              {ladderData.length > 0 && (
                <div className="border border-gray-200 dark:border-gray-700 rounded overflow-hidden">
                  <div className="overflow-x-auto">
                    <table className="w-full text-xs font-mono">
                      <thead className="bg-gray-50 dark:bg-gray-700">
                        <tr>
                          {/* Call columns */}
                          <th className="px-2 py-2 text-center border-r border-gray-200 dark:border-gray-600 font-semibold text-green-700 dark:text-green-400" colSpan={2 + ladderConfig.visibleGreeks.length}>
                            Calls
                          </th>
                          {/* Strike/Expiration column */}
                          <th className="px-2 py-2 text-center border-r border-gray-200 dark:border-gray-600 font-semibold text-gray-700 dark:text-gray-300">
                            {ladderConfig.mode === 'strike' ? 'Strike' : 'Expiration'}
                          </th>
                          {/* Put columns */}
                          <th className="px-2 py-2 text-center font-semibold text-red-700 dark:text-red-400" colSpan={2 + ladderConfig.visibleGreeks.length}>
                            Puts
                          </th>
                        </tr>
                        <tr className="text-xs text-gray-600 dark:text-gray-400">
                          {/* Call sub-headers */}
                          {ladderConfig.visibleGreeks.map(greek => {
                            const greekInfo = availableGreeks.find(g => g.key === greek);
                            return (
                              <th key={greek} className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                                {greekInfo?.label}
                              </th>
                            );
                          })}
                          <th className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">IV</th>
                          <th className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">Price</th>
                          {/* Center column */}
                          <th className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600 font-semibold">
                            {ladderConfig.mode === 'strike' ? '$' : 'Years'}
                          </th>
                          {/* Put sub-headers */}
                          <th className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                            Price
                          </th>
                          <th className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                            IV
                          </th>
                          {ladderConfig.visibleGreeks.map(greek => {
                            const greekInfo = availableGreeks.find(g => g.key === greek);
                            return (
                              <th key={greek} className="px-2 py-1 text-center">
                                {greekInfo?.label}
                              </th>
                            );
                          })}
                        </tr>
                      </thead>
                      <tbody>
                        {ladderData.map((row, index) => {
                          return (
                            <React.Fragment key={index}>
                              <tr className={`${index % 2 === 0 ? 'bg-white dark:bg-gray-800' : 'bg-gray-50 dark:bg-gray-800'} hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors`}>
                                {/* Call Greeks (outermost) */}
                                {ladderConfig.visibleGreeks.map(greek => {
                                  const greekInfo = availableGreeks.find(g => g.key === greek);
                                  return (
                                    <td key={greek} className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                                      {greekInfo?.format(row.call[greek]) || 'N/A'}
                                    </td>
                                  );
                                })}
                                {/* Call IV */}
                                <td className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                                  {formatPercentage(row.call.impliedVol)}
                                </td>
                                {/* Call Price (closest to center) */}
                                <td className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                                  {formatPrice(row.call.price)}
                                </td>
                                {/* Strike/Expiration (center) */}
                                <td className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600 font-semibold bg-gray-100 dark:bg-gray-700">
                                  {ladderConfig.mode === 'strike' ? `$${row.strike}` : `${row.expiration.toFixed(2)}y`}
                                </td>
                                {/* Put Price (closest to center) */}
                                <td className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                                  {formatPrice(row.put.price)}
                                </td>
                                {/* Put IV */}
                                <td className="px-2 py-1 text-center border-r border-gray-200 dark:border-gray-600">
                                  {formatPercentage(row.put.impliedVol)}
                                </td>
                                {/* Put Greeks (outermost) */}
                                {ladderConfig.visibleGreeks.map(greek => {
                                  const greekInfo = availableGreeks.find(g => g.key === greek);
                                  return (
                                    <td key={greek} className="px-2 py-1 text-center">
                                      {greekInfo?.format(row.put[greek]) || 'N/A'}
                                    </td>
                                  );
                                })}
                              </tr>
                            </React.Fragment>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* 📊 Price Chart Section - Independent */}
      {validation.isValid && ladderData.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <BarChart3 className="w-5 h-5 text-orange-600" />
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Price Chart</h2>
            </div>
            <button
              onClick={() => setIsChartExpanded(!isChartExpanded)}
              className="flex items-center space-x-1 px-3 py-1 bg-orange-600 text-white rounded text-sm hover:bg-orange-700 transition-colors"
            >
              <span>{isChartExpanded ? 'Hide Chart' : 'Show Chart'}</span>
              {isChartExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>
          </div>

          {/* Animated Chart Expansion */}
          <div className={`transition-all duration-300 ease-in-out overflow-hidden ${
            isChartExpanded ? 'max-h-none opacity-100' : 'max-h-0 opacity-0'
          }`}>
            {isChartExpanded && (
              <OptionChart
                data={ladderData}
                mode={ladderConfig.mode}
              />
            )}
          </div>
        </div>
      )}

      {/* 📈 Payoff Chart Section - Independent */}
      {validation.isValid && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <TrendingDown className="w-5 h-5 text-green-600" />
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Payoff Chart</h2>
            </div>
            <button
              onClick={() => setIsPayoffChartExpanded(!isPayoffChartExpanded)}
              className="flex items-center space-x-1 px-3 py-1 bg-green-600 text-white rounded text-sm hover:bg-green-700 transition-colors"
            >
              <span>{isPayoffChartExpanded ? 'Hide Chart' : 'Show Chart'}</span>
              {isPayoffChartExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>
          </div>

          {/* Animated Chart Expansion */}
          <div className={`transition-all duration-300 ease-in-out overflow-hidden ${
            isPayoffChartExpanded ? 'max-h-none opacity-100' : 'max-h-0 opacity-0'
          }`}>
            {isPayoffChartExpanded && (
              <PayoffChart
                parameters={parameters}
                strangleSpread={strangleSpread}
                calculateOptionPrice={calculateOptionPrice}
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default OptionPricingTool;

